3953	/****************************************************************************
3954	 * Name: yuv_to_rgb
3955	 *
3956	 * Description:
3957	 *   Shared YUV->RGB helper for dump diagnostics.
3958	 *   Input: Y, U, V as raw bytes (0-255).
3959	 *   Output: r, g, b clamped to 0-255.
3960	 *
3961	 ****************************************************************************/
3962	
3963	static void yuv_to_rgb(uint8_t y, uint8_t u, uint8_t v,
3964	                        int *r, int *g, int *b)
3965	{
3966	  int yi = (int)y;
3967	  int cb = (int)u - 128;
3968	  int cr = (int)v - 128;
3969	
3970	  *r = yi + cr + (cr * 51 / 128);
3971	  *g = yi - (cb * 28 / 81) - (cr * 365 / 512);
3972	  *b = yi + cb + (cb * 99 / 128);
3973	
3974	  if (*r < 0) *r = 0;  if (*r > 255) *r = 255;

